insert into public.collections(id,name,slug,description,status,cover_image) values('10000000-0000-4000-8000-000000000001','LUQA HOME','luqa-home','Anılarınızı saklamanın zarif yolu.','active','/images/home/heritage-clean.webp') on conflict(id) do nothing;
insert into public.products(collection_id,dimensions,materials,status,is_featured,is_published,price,currency,care,usage,created_at,id,name,slug,short_description,description,design_story) values('10000000-0000-4000-8000-000000000001','40 × 30 × 20 cm — üretim öncesi hedef ölçü; kesinleşmemiştir.','Cam görünümlü şeffaf paneller ve metalik altın tonlarında çerçeve hedeflenmektedir. Nihai malzeme ve üretim bilgileri henüz kesinleşmemiştir.','concept',true,true,null,'TRY','Bakım talimatları, nihai malzemeler ve üretim testleri tamamlandıktan sonra paylaşılacaktır.','Hatıralar, takılar ve özel eşyalar için dekoratif saklama konsepti. İç düzenleme seçenekleri geliştirme aşamasındadır.','2026-11-11T00:00:00Z','20000000-0000-4000-8000-000000000001','LUQA Heritage','luqa-heritage','Gelenekten ilham alan, zamansız bir hatıra.','Bordo, pembe ve beyaz çiçeklerin altın tonlu çerçeveyle buluştuğu cam hatıra kutusu konsepti. Sakladığınız her parçaya, yeni bir hikâye.','Bir çiçeğin zarafeti, bir hatıranın değeri. Heritage, geleneksel çiçek motiflerini modern bir formda yeniden yorumluyor.') on conflict(id) do nothing;
insert into public.product_images(product_id,image_url,alt_text,sort_order) select '20000000-0000-4000-8000-000000000001','/images/home/heritage-clean.webp','LUQA Heritage cam hatıra kutusu konsepti, bordo ve pembe çiçek detayları',0 where not exists(select 1 from public.product_images where product_id='20000000-0000-4000-8000-000000000001' and image_url='/images/home/heritage-clean.webp');
